<?php
require __DIR__.'/_init.php';$counts=[];foreach(['page','article','country','review','faq'] as $t){$q=db()->prepare('SELECT COUNT(*) FROM content WHERE type=?');$q->execute([$t]);$counts[$t]=(int)$q->fetchColumn();}$recent=db()->query('SELECT title,type,status,updated_at FROM content ORDER BY updated_at DESC LIMIT 8')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LipaHub dashboard</title><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"></head><body><div class="shell"><?php require __DIR__.'/_nav.php';?><main><div class="top"><div><small>OVERVIEW</small><h1>Welcome, <?=e(admin_user()['name'])?>.</h1></div><a href="<?=e(url('index.php'))?>" target="_blank">View website ↗</a></div><div class="stats"><?php foreach($counts as $k=>$v):?><div><small><?=e(ucfirst($k).'s')?></small><b><?=$v?></b><small>CMS entries</small></div><?php endforeach;?></div><section class="panel"><h2>Website control centre</h2><p>Manage the public website without editing code.</p><div class="quick"><a href="<?=e(url('admin/settings.php'))?>"><b>Site appearance & content</b><small>Brand, hero, footer, CTA, SEO, contact and media</small></a><a href="<?=e(url('admin/content.php?type=article'))?>"><b>Articles & guides</b><small>Create, edit, publish and reorder content</small></a><a href="<?=e(url('admin/content.php?type=review'))?>"><b>Reviews & testimonials</b><small>Manage stories and reviewer names</small></a><a href="<?=e(url('admin/content.php?type=country'))?>"><b>Country pages</b><small>Publish location-specific guides</small></a></div></section><section class="panel"><h2>Recently updated content</h2><div class="table-wrap"><table><tr><th>Title</th><th>Type</th><th>Status</th><th>Updated</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['type'])?></td><td><?=e($r['status'])?></td><td><?=e(date('M j, Y',strtotime($r['updated_at'])))?></td></tr><?php endforeach;?></table></div></section></main></div></body></html>